
open(OUT, ">output/IJM_stats.html") || die;


#NATIVE	ISOETACEAE	Isoetes	bolanderi	Engelm.				Isoetes bolanderi	Isoetes bolanderi Engelm.		syn: Isoetes bolanderi var. pygmaea (Engelm.) Clute		TJM1	LYCOPHYTES	0
#open(IN, "output/accepted_names.out") || die; old file name generated by get_IJM_names & tabbify
open(IN, "output/accepted_names_out.txt") || die; #new file generated by SQL database file make_main_table 

	while(<IN>){

	($LN,$nativity, $family, $genus, $species, $species_author, $infraspecific_rank, $infraspecific_epithet, $infraspecific_author, $name_minus_authors, $name_plus_authors, $synonyms, $common, $TJM1_TJM2, $major_clade, $endemicity)=split(/\t/);
	$MC{$family}=$major_clade;
	
	if($infraspecific_rank !~ /^ *$/){
		++$rank;

		if($infraspecific_epithet =~ /^ *$/){
		 print "epithet empty but rank present:".$name_minus_authors."\n";
		}

	}
	else{
		if($infraspecific_epithet !~ /^ *$/){
		 print "rank empty but epithet present:".$name_minus_authors."\n";
		}
	}


	if($infraspecific_epithet !~ /^ *$/){
		++$epi;
	}

	
	
	$nativity =~ s/'//g;
	
	$genus_count++ unless $seen{$genus}++;
		
		if($nativity =~ /^NATIVE OR NATURALIZED$/){
			$native_species{$family}++ unless $seen{"$genus $species"}++;
				if($infraspecific_epithet){
					$native_MRT{$family}++;
					$seen_MRT{"$genus $species"}++;
					#print $nativity."\t".$name_minus_authors."\n";
				}
				else{
					$native_MRT{$family}++ unless $seen_MRT{"$genus $species"};
					#print $nativity."\t".$name_minus_authors."\n" unless $seen_MRT{"$genus $species"};
				}
		$count_NNGenera{$family}++ unless $seen_NNG{$genus}++;
		$NN{$family}{$genus}++;
		}
		elsif($nativity =~ /^NATIVE$/){
			$native_species{$family}++ unless $seen{"$genus $species"}++;
				if($infraspecific_epithet){
					$native_MRT{$family}++;
					$seen_MRT{"$genus $species"}++;
					#print $nativity."\t".$name_minus_authors."\n";
				}
				else{
					$native_MRT{$family}++ unless $seen_MRT{"$genus $species"};
					#print $nativity."\t".$name_minus_authors."\n" unless $seen_MRT{"$genus $species"};
				}
		$count_NNGenera{$family}++ unless $seen_NNG{$genus}++;
		$NN{$family}{$genus}++;
		}
		elsif($nativity=~/^NATURALIZED$/){
			$naturalized_species{$family}++ unless $seen{"$genus $species"}++;
				if($infraspecific_epithet){
					$naturalized_MRT{$family}++;
					$seen_MRT{"$genus $species"}++;
					#print $nativity."\t".$name_minus_authors."\n";
				}
				else{
					$naturalized_MRT{$family}++ unless $seen_MRT{"$genus $species"};
					#print $nativity."\t".$name_minus_authors."\n" unless $seen_MRT{"$genus $species"};
				}
			$count_NNGenera{$family}++ unless $seen_NNG{$genus}++;
			$NN{$family}{$genus}++;
		}
		#if($nativity !~ m/^(NATIVE|NATURALIZED)/){
		elsif( ($nativity !~ /^NATIVE OR NATURALIZED$/) || ($nativity !~/^NATURALIZED$/) || ($nativity !~ /^NATIVE$/) ){
			$waif_species{$family}++ unless $seen{"$genus $species"}++;
				if($infraspecific_epithet){
					$waif_MRT{$family}++;
					$seen_MRT{"$genus $species"}++;
					#print $nativity."\t".$name_minus_authors."\n";
				}
				else{
					$waif_MRT{$family}++ unless $seen_MRT{"$genus $species"};
					#print $nativity."\t".$name_minus_authors."\n" unless $seen_MRT{"$genus $species"};

				}
			$count_WAIFGenera{$family}++ unless $seen_WAIF{$genus}++;
			$WAIF{$family}{$genus}++;
		}
		else{
			#if( ($nativity !~ /^NATIVE OR NATURALIZED$/) || ($nativity !~/^NATURALIZED$/) || ($nativity !~ /^NATIVE$/) ){
				print "SKIPPED NATIVITY-->".$nativity."\n\n";
			#}
		
		}
	
	if($endemicity ==1){
		if($infraspecific_epithet){
			$endemic_MRT{$family}++;
		}
		else{
			$endemic_MRT{$family}++ unless $seen_MRT{"$genus $species"};
		}
	}
}






